struct mobj *allocate_user_ta_memory(size_t size) {
    size_t granularity = sysconf(_SC_PAGESIZE); // Assuming allocation granularity is page size
    size_t rounded_size = ((size + granularity - 1) / granularity) * granularity;

    struct mobj *mobj = NULL;

    if (CONFIG_PAGED_USER_TA == 1) {
        mobj = mobj_paged_alloc(rounded_size);
    } else {
        mobj = mobj_mm_alloc(rounded_size, 0);
    }

    if (mobj != NULL) {
        // Initialize the memory to zero
        memset(mobj->ptr, 0, rounded_size);
    }

    return mobj;
}

