struct mobj *allocate_mobj_user_ta(size_t size) {
    struct mobj *mobj = NULL;
    size_t rounded_size;

    if (config_paged_user_ta_enabled()) {
        mobj = mobj_paged_alloc(size);
    } else {
        mobj = mobj_mm_alloc(size, 0, 0);
    }

    if (mobj != NULL) {
        rounded_size = ROUND_UP(size, ALLOC_GRANULARITY);
        memset(mobj->base, 0, rounded_size);
        mobj->size = rounded_size;
    }

    return mobj;
